import { useEffect } from 'react';
import { useInView } from 'react-intersection-observer';
import { LoadingSpinner } from '~/widgets/loading/loading-spinner';
import { useWalletHistoryListInfiniteQuery } from '~/entities/wallet/api/use-wallet-history-list-infinite-query';
import { DisplayAmount } from '~/entities/wallet/ui/wallet-history/display-amount';

type VoucherHistoryListProps = {
  vouchId?: string;
};

export const VoucherHistoryList = ({ vouchId }: VoucherHistoryListProps) => {
  const [ref, inView] = useInView();
  const { data, hasNextPage, fetchNextPage, isFetchingNextPage, isLoading } = useWalletHistoryListInfiniteQuery({
    search: { vouchId },
  });

  useEffect(() => {
    if (hasNextPage && inView) fetchNextPage();
  }, [hasNextPage, inView, fetchNextPage]);

  // select 단계의 restructureList 가 각 항목에 time/title 을 채워준다
  const list = data?.pages?.flatMap((page) => page.result?.list ?? []) ?? [];

  if (isLoading) {
    return <LoadingSpinner />;
  }

  if (list.length === 0) {
    return (
      <div className="history-empty-wrapper">
        <p className="history-empty-text">이용 내역이 없습니다.</p>
      </div>
    );
  }

  return (
    <>
      <ul className="history-list">
        {list.map((item, index) => (
          <li className="history-item" key={item.trnscId ?? index} ref={index + 1 === list.length ? ref : undefined}>
            <div className="item-left">
              <span className="history-datetime common-font-roboto">{item.time}</span>
              <p className="history-name">{item.title}</p>
            </div>
            <DisplayAmount amount={item.trnscAmt} type={item.rcppaySttusCd} />
          </li>
        ))}
      </ul>
      {isFetchingNextPage && (
        <div className="common-pagination">
          <span className="page-dot"></span>
          <span className="page-dot"></span>
          <span className="page-dot"></span>
          <span className="page-dot"></span>
        </div>
      )}
    </>
  );
};
