import type { ReactNode } from 'react';
import { overlay } from '~/shared/lib/overlay';
import { BottomSheet } from '~/shared/ui/bottom-sheets/bottom-sheet';

export type ShopBottomSheetProps = {
  title?: string | JSX.Element;
  description?: string | JSX.Element;
  children: ReactNode;
  onClose?: () => void;
};

export const useShopBottomSheet = () => {
  const openShopBottomSheet = (shopBottomSheet: ShopBottomSheetProps) => {
    const { children, title = '', description = '' } = shopBottomSheet;

    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      const key = new Date().getTime();
      return (
        <BottomSheet
          title={title}
          description={description}
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
          overlayClassName="sheet-voucher-merchants"
          key={key}
        >
          {children}
        </BottomSheet>
      );
    });
  };

  return { openShopBottomSheet, closeBottomSheet: overlay.closeAll };
};
