import { format } from 'date-fns';
import { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { VoucherHistoryList } from '~/pages/voucher/ui/voucher-history-list';
import { VoucherMerchantList } from '~/pages/voucher/ui/voucher-merchant-list';
import { FullScreenLoading } from '~/widgets/loading/full-screen-loading';
import { useGetRouterState } from '~/entities/exchange/lib/use-get-router-state';
import { useGetShopListMutation } from '~/entities/shop/api/use-get-shop-list-mutation';
import type { Place } from '~/entities/shop/model/types';
import { VoucherItemDTO } from '~/entities/voucher/api/dtos/voucher-item';
import { getVoucherBadgeClass } from '~/entities/voucher/lib/get-voucher-badge-class';
import { VoucherType } from '~/shared/api/dtos/enums';
import { MAX_INPUT_NUMBER } from '~/shared/constants/form';
import i18n from '~/shared/i18n/i18n';
import { useShopBottomSheet } from '~/shared/lib/hooks/use-shop-bottom-sheet';
import { parseToDate } from '~/shared/lib/web-view-bridge';

export const VoucherDetailPage = () => {
  const { routerState } = useGetRouterState<{ vouchId: string }>();
  const { vouchId } = routerState;
  const { state } = useLocation();
  const { openShopBottomSheet } = useShopBottomSheet();
  const todayDate = format(new Date(), 'yyyyMMdd');
  const detail = (state ?? {}) as VoucherItemDTO;
  const [shopList, setShopList] = useState<Place[]>([]);
  const { mutateAsync: getShopList, isPending } = useGetShopListMutation();

  useEffect(() => {
    if (!state) return;
    let active = true;

    void getShopList().then((response) => {
      if (active) setShopList(response ?? []);
    });

    return () => {
      active = false;
    };
  }, [getShopList, state]);

  const fnFormattedAmount = (num?: string | number | null): string => {
    if (num === null || num === undefined || Number(num) < 0 || isNaN(Number(num))) return '';
    const numAmt = Number(num);
    if (numAmt > MAX_INPUT_NUMBER) {
      return MAX_INPUT_NUMBER.toLocaleString();
    }
    return numAmt.toLocaleString();
  };

  const handleOpenBottomSheet = () => {
    openShopBottomSheet({
      title: `${detail.vouchNm ?? ''} 사용처`,
      children: <VoucherMerchantList shopList={shopList} voucherPlaces={detail.place ?? []} />,
    });
  };

  const isExpired = todayDate > parseToDate(detail.rcvfverUseEndDt, 'yyyyMMdd');
  const usagePeriod = `${parseToDate(detail.rcvfverUseStartDt, 'yyyy.MM.dd')} ~ ${parseToDate(detail.rcvfverUseEndDt, 'yyyy.MM.dd')}`;

  return (
    <>
      {isPending && <FullScreenLoading />}
      <div className="page-voucher-detail-KBB KBB">
        <main>
          <section className="voucher-summary-container">
            <div className="summary-top">
              {isExpired ? (
                <div className="badge-group">
                  <span className={`common-badge ${getVoucherBadgeClass(detail.vouchTyCd)}`}>{detail.vouchTyNm}</span>
                  <span className="common-badge badge-cancel">{i18n.t('expired')}</span>
                </div>
              ) : (
                <span className={`common-badge ${getVoucherBadgeClass(detail.vouchTyCd)}`}>{detail.vouchTyNm}</span>
              )}
              <div className="title-amount-row">
                <h2 className="voucher-title">{detail.vouchNm}</h2>
                <div className="voucher-amount">
                  <span className="val-num common-font-roboto">{fnFormattedAmount(detail.pbmBalanceOf ?? 0)}</span>
                  <span className="val-unit">{i18n.t('won')}</span>
                </div>
              </div>
            </div>

            <div className="summary-info-list">
              <div className="info-row">
                <span className="info-label">{i18n.t('issuer')}</span>
                <span className="info-value">{detail.insttNm}</span>
              </div>
              <div className="info-row">
                <span className="info-label">{i18n.t('usageConditions')}</span>
                <span className="info-value">{detail.pymntCond}</span>
              </div>
              <div className="info-row">
                <span className="info-label">{i18n.t('issuedAmount')}</span>
                <span className="info-value voucher-amount-wrapper">
                  <span className="voucher-amount-value common-font-roboto">
                    {fnFormattedAmount(detail.pymntAmt ?? 0)}
                  </span>
                  <span className="voucher-amount-won">{i18n.t('won')}</span>
                </span>
              </div>
              <div className="info-row">
                <span className="info-label">{i18n.t('usagePeriod')}</span>
                <span className="info-value common-font-roboto">{usagePeriod}</span>
              </div>
            </div>

            <div className="summary-bottom-link">
              <button type="button" className="btn-merchant-link" onClick={handleOpenBottomSheet}>
                <span>{i18n.t('checkAvailableMerchants')}</span>
                <i className="icon-arrow-right-16" aria-hidden="true"></i>
              </button>
            </div>
          </section>

          <div className="divider-container" aria-hidden="true"></div>

          {detail.type === VoucherType.내_바우처 && (
            <section className="voucher-history-container">
              <h3 className="history-section-title">{i18n.t('usageHistory')}</h3>
              <VoucherHistoryList vouchId={vouchId} />
            </section>
          )}
        </main>
        <div id="listMap" hidden></div>
      </div>
    </>
  );
};
